type EventType = 'requirement' | 'scale' | 'failure' | 'business' | 'team' | 'time' | 'constraint' | 'boss'
interface HealthDelta { coupling?: number; cohesion?: number; extensibility?: number; complexity?: number; reliability?: number; debt?: number }
interface DecisionOption { id: 'A' | 'B' | 'C'; label: string; description: string; healthDelta: HealthDelta; tags: string[]; consequence: string }
interface StageEvent { type: EventType; title: string; description: string; icon: string; decisions?: DecisionOption[]; requiresDesign: boolean; hint?: string; successCriteria?: string }
interface Stage { id: string; order: number; title: string; event: StageEvent; isBoss: boolean; isCheckpoint: boolean; failureExplanation?: string }
interface RoguelikeScenario {
  slug: string; title: string; icon: string; description: string; systemContext: string; initialRequirement: string
  difficulty: 'hard'; modes: string[]; stages: Stage[]
  initialConstraints: { complexityBudget: number; engineeringHours: number; teamSize: number; infraBudget: number; maxStructuralChanges: number; expectedUsers: string }
  tags: string[]; status: 'published'; order: number; estimatedMinutes: number
}

// ─── Authoring helpers (keep the data below compact; output is plain RoguelikeScenario data) ───

const MODES = ['interview', 'survival', 'hardcore', 'endless']

/** Build a decision option. */
function d(
  id: 'A' | 'B' | 'C',
  label: string,
  description: string,
  healthDelta: HealthDelta,
  tags: string[],
  consequence: string,
): DecisionOption {
  return { id, label, description, healthDelta, tags, consequence }
}

interface StageOpts {
  design?: boolean
  checkpoint?: boolean
  hint?: string
  success?: string
  decisions?: DecisionOption[]
  failure?: string
}

/** Returns a stage factory bound to a scenario slug. Applies 🐉 BOSS: / 🔥 INCIDENT: prefixes automatically. */
function stageFactory(slug: string) {
  return (
    order: number,
    title: string,
    type: EventType,
    eventTitle: string,
    description: string,
    icon: string,
    o: StageOpts = {},
  ): Stage => {
    const boss = type === 'boss'
    const incident = type === 'failure'
    const prefix = boss ? '🐉 BOSS: ' : incident ? '🔥 INCIDENT: ' : ''
    const event: StageEvent = {
      type,
      title: `${prefix}${eventTitle}`,
      description: `${prefix}${description}`,
      icon,
      requiresDesign: !!o.design,
    }
    if (o.decisions) event.decisions = o.decisions
    if (o.hint) event.hint = o.hint
    if (o.success) event.successCriteria = o.success
    const stage: Stage = {
      id: `${slug}-stage-${order}`,
      order,
      title: boss ? `🐉 BOSS: ${title}` : title,
      event,
      isBoss: boss,
      isCheckpoint: !!o.checkpoint,
    }
    if (o.failure) stage.failureExplanation = o.failure
    return stage
  }
}

